import { expect, test } from '@playwright/test'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import type { BookOut, ChapterOut } from '../src/api/types'

// Original fixture generated by backend/tests/fixtures/toc_epub.py::nested_epub.
// Only imports and reads an isolated book; never submits model processing.
const fixture = path.join(path.dirname(fileURLToPath(import.meta.url)), 'fixtures/nested-toc.epub')

test('EPUB保留四层目录，父章可阅读，子目录可展开且窄屏不溢出', async ({ page }, testInfo) => {
  await page.setViewportSize({ width: 1280, height: 900 })
  await page.goto('/library')
  await page.setInputFiles('[data-testid=import-file-input]', fixture)
  await page.getByTestId('import-submit').click()
  await expect(page.getByTestId('import-result')).toContainText('导入完成：EPUB')
  await page.getByTestId('book-card').filter({
    has: page.getByRole('heading', { name: '原创 EPUB 样例', exact: true }),
  }).getByRole('link', { name: '开始阅读' }).click()
  const nav = page.getByRole('navigation', { name: '章节导航' })
  const root = nav.locator('.ndr-toc-tree > li > .ndr-collapsible-block').filter({
    has: page.getByRole('heading', { name: '作品', exact: true }),
  }).first()
  await expect(root).toBeVisible()
  const volume = root.locator(':scope > [aria-labelledby] > ol > li > .ndr-collapsible-block').first()
  const chapter = volume.locator(':scope > [aria-labelledby] > ol > li > .ndr-collapsible-block').first()
  await expect(volume.locator(':scope > .ndr-collapsible-heading > h3')).toHaveText('第一卷')
  await expect(chapter.locator(':scope > .ndr-collapsible-heading > h3')).toHaveText('第一章')
  await expect(chapter.locator(':scope > [aria-labelledby] > .ndr-toc-tree .ndr-chapter-title')).toHaveText('第二节')
  const content = page.getByTestId('document-renderer')
  await expect(content).toContainText('父章正文。')
  await content.evaluate(element => element.setAttribute('data-toc-stable', 'true'))
  await nav.getByRole('button', { name: /第一卷.*未处理/ }).click()
  await expect(content).toContainText('父章正文。')
  await nav.getByRole('button', { name: '展开第一章', exact: true }).click()
  await expect(chapter.locator('.ndr-chapter-title').filter({ hasText: '第二节' })).toBeVisible()
  await nav.getByRole('button', { name: '收起第一章', exact: true }).click()
  await expect(chapter.locator('.ndr-chapter-title').filter({ hasText: '第二节' })).toBeHidden()
  await expect(chapter.locator('.ndr-chapter-title').filter({ hasText: /^第一章$/ })).toBeHidden()
  await expect(chapter.locator(':scope > .ndr-collapsible-summary .ndr-chapter')).toHaveCount(0)
  await expect(content).toHaveAttribute('data-toc-stable', 'true')
  await nav.getByRole('button', { name: '展开第一章', exact: true }).click()
  await expect(chapter.locator('.ndr-chapter-title').filter({ hasText: /^第一章$/ })).toBeVisible()
  await nav.locator('.ndr-chapter-title').filter({ hasText: /^第二节$/ }).click()
  await expect(content).toContainText('第二节。')
  await content.evaluate(element => element.setAttribute('data-toc-stable', 'true'))
  await page.screenshot({ path: testInfo.outputPath('toc-desktop.png'), fullPage: true })
  await page.setViewportSize({ width: 360, height: 800 })
  await expect(nav).toBeVisible()
  await expect.poll(() => page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth)).toBeLessThanOrEqual(1)
  await expect(content).toHaveAttribute('data-toc-stable', 'true')
  await page.screenshot({ path: testInfo.outputPath('toc-mobile.png'), fullPage: true })
})

test('重复卷入口只在下级保留，收起无灰色章节框且正文保持不变', async ({ page }, testInfo) => {
  await page.setViewportSize({ width: 1280, height: 900 })
  await page.goto('/library')
  await page.getByTestId('import-file-input').setInputFiles({
    name: '原创重复目录.txt', mimeType: 'text/plain',
    buffer: Buffer.from('第一章 封面\n\n纸船停在桥下。\n「明天再来。」小禾说。\n\n第二章 晴天\n\n风吹过新叶。'),
  })
  await page.getByTestId('import-submit').click()
  await expect(page.getByTestId('import-result')).toContainText('导入完成：TXT')
  // Keep real isolated import/content/progress APIs; only replace the TOC response.
  await page.route(/\/api\/books\/[^/?]+$/, async route => {
    const response = await route.fetch()
    const body = await response.json() as { data: BookOut }
    const chaptersResponse = await page.request.get(`${route.request().url()}/chapters`)
    const { data: chapters } = await chaptersResponse.json() as { data: ChapterOut[] }
    const chapter = chapters[0]
    if (body.data.active_version) body.data.active_version.toc = [
      { id: 'volume', parent_id: null, title: '第一卷', chapter_id: chapter.id, target_cp: chapter.start_cp },
      { id: 'part', parent_id: 'volume', title: '卷首', chapter_id: chapter.id, target_cp: chapter.start_cp },
      { id: 'cover', parent_id: 'part', title: '封面', chapter_id: chapter.id, target_cp: chapter.start_cp },
    ]
    await route.fulfill({ response, json: body })
  })
  await page.getByTestId('book-card').filter({ hasText: '原创重复目录' }).getByRole('link', { name: '开始阅读' }).click()
  const nav = page.getByRole('navigation', { name: '章节导航' })
  const volume = nav.locator('.ndr-toc-tree > li > .ndr-collapsible-block').filter({
    has: page.getByRole('heading', { name: '第一卷', exact: true }),
  }).first()
  const content = page.getByTestId('document-renderer')
  await expect(content).toContainText('纸船停在桥下。')
  await content.evaluate(element => element.setAttribute('data-toc-stable', 'true'))
  await expect(volume.locator('.ndr-chapter-title')).toHaveText('封面')
  await nav.getByRole('button', { name: '收起第一卷', exact: true }).click()
  await expect(volume.locator('.ndr-chapter')).toBeHidden()
  await expect(volume.locator(':scope > .ndr-collapsible-summary .ndr-chapter')).toHaveCount(0)
  await expect(volume.getByRole('group', { name: /^第一卷：共 1 章/ })).toBeVisible()
  await page.screenshot({ path: testInfo.outputPath('toc-collapsed-desktop.png'), fullPage: true })
  await page.setViewportSize({ width: 360, height: 800 })
  await page.screenshot({ path: testInfo.outputPath('toc-collapsed-mobile.png'), fullPage: true })
  await nav.getByRole('button', { name: '展开第一卷', exact: true }).click()
  await volume.locator('.ndr-chapter-title').click()
  await expect(content).toHaveAttribute('data-toc-stable', 'true')
  await expect(content).toContainText('纸船停在桥下。')
  await expect.poll(() => page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth)).toBeLessThanOrEqual(1)
})
